"""Add grouped policy pages to the administrator library."""
from datetime import datetime, timezone
from alembic import op
import sqlalchemy as sa
revision = "0022"
down_revision = "0021"
branch_labels = None
depends_on = None

# Rewritten from the corresponding journal policy pages at eelet.org.uk.
PAGES = [
("Publication Ethics and Policies", "publication-ethics-policies", "Ethics", """<h2>Responsible research and publication</h2><p>Submissions must present original work, acknowledge relevant sources and identify everyone who made a substantial scholarly contribution. Authors are responsible for accurate reporting, appropriate research approvals, participant consent and disclosure of funding or competing interests. Fabricated findings, misleading images and simultaneous submissions are unacceptable.</p><h3>Editorial responsibilities</h3><p>Editors assess manuscripts fairly, protect confidential material and manage conflicts of interest. Independent reviewers should provide constructive, evidence-based assessments and decline assignments when their expertise, availability or relationships could compromise a fair review.</p><h3>Concerns, corrections and appeals</h3><p>Suspected misconduct is examined carefully, with an opportunity for the parties concerned to respond. Depending on the evidence, the journal may request clarification, reject a manuscript, publish a correction or issue a linked retraction notice. Readers and authors should contact the editorial office with specific evidence when raising a concern or appealing a decision.</p>"""),
("Copyright and Licensing", "copyright-and-licensing", "Ethics", """<h2>Rights and reuse</h2><p>Authors retain copyright in their work and grant the journal permission to publish and distribute the accepted article. Authors must obtain permission for material belonging to others and clearly identify any content subject to separate restrictions.</p><h3>Open-access licensing</h3><p>The journal's published copyright and licence information determines the terms of reuse. Where Creative Commons Attribution 4.0 applies, readers may share and adapt the work, including for commercial purposes, provided they acknowledge the authors, cite the publication, identify the licence and indicate any changes.</p><h3>Author sharing</h3><p>Authors may share permitted versions through teaching materials, personal websites or repositories in accordance with the applicable licence. Include the article title, authors, journal, publication year and DOI where available. Third-party material may require additional permission even when the surrounding article is openly licensed. Contact the editorial office if ownership or reuse conditions are unclear.</p>"""),
("Generative AI Policy", "generative-ai-policy", "Ethics", """<h2>Responsible use of AI-assisted tools</h2><p>AI tools may assist with language editing, formatting or carefully checked analytical tasks. Authors remain fully responsible for the originality, accuracy and integrity of every part of their manuscript. Tools cannot qualify as authors or replace scholarly judgement.</p><h3>Disclosure and verification</h3><p>Describe substantive use in the methods or acknowledgements, naming the tool and explaining its purpose and extent. Verify all generated statements, references, calculations and outputs. Never use generated material to fabricate data, invent citations or misrepresent research findings.</p><h3>Confidentiality during review</h3><p>Editors and reviewers must protect unpublished manuscripts and personal information. They should not upload confidential submission material to external AI services or delegate editorial recommendations to automated tools without an explicitly authorised, confidential process. Undisclosed or misleading use may result in requests for clarification, rejection or further editorial action.</p>"""),
("Disclaimer", "disclaimer", "Ethics", """<h2>Responsibility for published material</h2><p>Articles express their authors' views. Publication does not imply endorsement by the journal, its editors or its publisher. Authors are responsible for their research claims, source acknowledgements, permissions and compliance with ethical requirements.</p><p>Editorial assessment and peer review aim to support reliable scholarship, but they do not guarantee that every statement is complete, accurate or suitable for a particular purpose. Readers should evaluate information independently before relying on it.</p><p>External resources, where provided, are offered for reference and do not constitute endorsement. Their content and availability are outside the journal's control. Concerns about errors, rights or published material should be sent to the editorial office for assessment. This notice does not exclude rights or responsibilities that cannot lawfully be excluded.</p>"""),
("Author Guidelines", "author-guidelines", "For Authors", """<h2>Prepare your manuscript</h2><p>Submit original research that fits the journal's scope. Provide a clear title, author names and affiliations, corresponding-author details, a concise abstract and relevant keywords. Organise the paper into appropriate sections such as introduction, methods, findings, discussion and conclusion.</p><h3>Presentation and references</h3><p>Use readable typography and consistent headings. Number tables and figures, supply informative captions and acknowledge any reused material. Apply one recognised citation style consistently and include persistent identifiers where available. State funding, competing interests, ethical approvals and relevant acknowledgements.</p><h3>Submit and respond</h3><p>Use this website's Submission page to enter your contact information and article details, attach a PDF and complete the CAPTCHA. Check the journal's current requirements before submitting. Do not submit the same manuscript elsewhere while it is under consideration.</p><p>Editors may request revisions following review. Respond to each comment clearly and explain substantial changes. Consult the journal's published policies for review arrangements, licensing and any applicable charges; submission does not guarantee acceptance.</p>"""),
("Plagiarism Policy", "plagiarism-policy", "For Authors", """<h2>Originality and attribution</h2><p>Authors must acknowledge the words, ideas, images and data of others. Uncredited copying, close paraphrasing, misleading reuse of earlier work and duplicate publication breach publication standards. Quote borrowed wording accurately and distinguish it from your own contribution.</p><h3>Assessment</h3><p>The editorial team may examine similarity reports alongside the manuscript and its sources. A numerical score alone does not establish misconduct: context, attribution and the nature of the overlap matter. Follow the similarity requirements stated by the journal.</p><h3>Editorial action</h3><p>Limited, correctable overlap may require revision. Serious or deliberate misrepresentation may lead to rejection. Concerns arising after publication can result in a correction or retraction, with further notification where justified. Authors will be asked to explain relevant evidence as part of a fair assessment.</p><p>Report suspected plagiarism to the editorial office with the article details and supporting sources. All contributors share responsibility for checking originality before submission.</p>"""),
("Peer Review Policy", "peer-review-policy", "For Authors", """<h2>Independent assessment</h2><p>Editors first assess scope, completeness, presentation and research integrity. Suitable manuscripts are normally sent to independent subject specialists who consider originality, methods, evidence, clarity and scholarly relevance. Reviewers must disclose conflicts and protect confidential material.</p><h3>Review arrangements</h3><p>The journal's stated review model applies. In single-blind review, reviewers know the authors' identities while reviewer identities remain confidential. Authors should follow any additional anonymisation instructions for journals using a different model.</p><h3>Decisions and revisions</h3><p>Outcomes may include acceptance, minor revision, major revision or rejection. The editor makes the final decision after considering the reports and the manuscript's suitability. Revised submissions should include a clear response to each review point and explain changes or reasoned disagreements.</p><p>Review times vary with specialist availability and revision requirements. Authors may contact the editorial office for an update or submit an evidence-based appeal. Decisions should reflect scholarly merit rather than personal relationships or commercial considerations.</p>"""),
("Contact Us", "contact-us", "", """<h2>Contact the editorial office</h2><p>For questions about the journal, its editorial policies or a manuscript under consideration, contact the editorial office using the email address provided below.</p><h3>Manuscript enquiries</h3><p>Include the article title, corresponding author's name and any reference number when asking about an existing submission. To send a new manuscript, please use the Submission page and complete the required form.</p><h3>Other enquiries</h3><p>Clearly identify requests concerning permissions, corrections, publication ethics or technical difficulties. Include enough information for the editor to investigate, but avoid sending sensitive personal information unnecessarily.</p>""")
]

def upgrade():
    for table in ("web_pages", "editor_journal_pages"):
        op.add_column(table, sa.Column("menu_group", sa.String(40), nullable=False, server_default=""))
    pages = sa.table("web_pages", sa.column("title",sa.String), sa.column("slug",sa.String), sa.column("content_html",sa.Text), sa.column("menu_group",sa.String), sa.column("created_at",sa.DateTime), sa.column("updated_at",sa.DateTime))
    db=op.get_bind()
    now=datetime.now(timezone.utc)
    for title,slug,group,content in PAGES:
        if db.execute(sa.select(pages.c.slug).where(pages.c.slug==slug)).first():
            db.execute(pages.update().where(pages.c.slug==slug).values(menu_group=group))
        else:
            db.execute(pages.insert().values(title=title,slug=slug,menu_group=group,content_html=content,created_at=now,updated_at=now))

def downgrade():
    # Retain library content because administrators may have edited it.
    op.drop_column("editor_journal_pages","menu_group")
    op.drop_column("web_pages","menu_group")
